/**
 * 负责 平民 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { roleName, text } from "@ai-werewolf-arena/game-text";
/** 文件说明：平民角色 profile。 */
import { Camp, Role } from "../../../../core/domain/model";
import { NativeRoleContributions } from "../contracts";

/** 平民角色配置。 */
export const VILLAGER_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Villager,
    camp: Camp.Good,
    label: roleName("villager"),
    skillBrief: text("zh-CN", "role.villager.brief"),
    goodSide: "villager",
  },
  runtime: {},
  presentation: nativeRolePresentation("villager"),
};

/**
 * 负责玩家胜利归属组件的结构与创建。输入为明确 affiliations，输出经共享 reader 校验复制后的组件；胜利归属与 Role.camp、技能独立。
 * 运行组件仍归 World 持有，创建器不推断真实阵营、不选择胜者或授予行动许可。
 */
import type { VictoryAffiliation } from "@ai-werewolf-arena/game-contract";
import { readVictoryAffiliations } from "@ai-werewolf-arena/replay-contract";

/** 独立胜利成员归属，与 Role.camp 和能力刻意分开。 */
export interface VictoryComponent {
  affiliations: VictoryAffiliation[];
}
export function createVictoryComponent(
  affiliations: readonly VictoryAffiliation[],
): VictoryComponent {
  return { affiliations: readVictoryAffiliations(affiliations) };
}

import { BoardConfig, Role, WinCondition } from "../../core/domain/model";

/**
 * 6 人 MVP：最小闭环板子，用于验证基础夜昼流转与守卫/预言家核心规则。
 */
export const sixPlayerMvpConfig: BoardConfig = {
  boardSize: 6,
  enableSheriff: false,
  winConditions: [WinCondition.SlaughterCity, WinCondition.WolfReachHalf],
  hooks: {
    onDaybreak: false,
    onPreElection: false,
    onPreVote: false,
    onPerSpeechGap: false,
  },
  roleSetups: [
    { role: Role.Wolf, count: 2 },
    { role: Role.Villager, count: 2 },
    { role: Role.Seer, count: 1 },
    { role: Role.Guard, count: 1 },
  ],
};

/**
 * 负责实际装配角色资料、运行与展示。输入是原自定义 flat profile 或明确三贡献集合，默认使用
 * 原 55 角色的登记顺序；输出为唯一默认 Catalog 或独立 Catalog。捕获函数在此实际注入，
 * 不在 profile 声明时建立反向展示依赖。初始化／显示仍由 Catalog 在原时点执行，不复制状态。
 */
import { RoleCatalog } from "./catalog";
import type { RoleContributions, RoleProfile, NativeRoleContributions } from "./contracts";

export function createRoleCatalog(
  input?: readonly RoleProfile[] | { contributions: readonly RoleContributions[] },
): RoleCatalog {
  // 登记也在实际装配时加载，避免单独导入某个角色时经运行查询绕回尚未初始化的登记表。
  const { BUILTIN_ROLE_CONTRIBUTIONS } =
    require("./builtin-contributions") as typeof import("./builtin-contributions");
  const resolved = input ?? { contributions: BUILTIN_ROLE_CONTRIBUTIONS };
  const builtinMetadata = BUILTIN_ROLE_CONTRIBUTIONS.map((entry) => entry.metadata);
  if (Array.isArray(resolved)) return new RoleCatalog(resolved, builtinMetadata);
  // 仅在实际装配原生运行时加载完整捕获；声明及纯自定义接入不提前初始化展示依赖。
  const { captureNativeRolePresentation } =
    require("../../observation/native-role-presentation-capture") as typeof import("../../observation/native-role-presentation-capture");
  return new RoleCatalog(
    {
      contributions: (resolved as { contributions: readonly RoleContributions[] }).contributions,
      renderNative: captureNativeRolePresentation,
    },
    builtinMetadata,
  );
}

let defaultCatalog: RoleCatalog | null = null;

/** 默认实例只缓存实际装配的 Catalog，不保存另一份角色状态或展示结果。 */
export function getDefaultRoleCatalog(): RoleCatalog {
  if (!defaultCatalog) defaultCatalog = createRoleCatalog();
  return defaultCatalog;
}

/** 按原顺序公开组合声明的副本；保留每份贡献引用，不向调用者开放登记数组写权。 */
export function getDefaultRoleContributions(): readonly NativeRoleContributions[] {
  const { BUILTIN_ROLE_CONTRIBUTIONS } =
    require("./builtin-contributions") as typeof import("./builtin-contributions");
  return Array.from(BUILTIN_ROLE_CONTRIBUTIONS);
}
